def backfill_sales_channels_and_clear_fake_gia(apps, schema_editor):
    """
    1. Backfill empty sales_channels on existing products to all 3 channels so
       existing active catalog items remain visible after channel filtering.
    2. IRREVERSIBLE DATA FIX: Clear default certificate_agency='GIA' on products
       that have neither certificate_number nor a CERTIFICATE_PDF media file.
    """
    ProductModel = apps.get_model("catalog", "ProductModel")
    ProductMedia = apps.get_model("catalog", "ProductMedia")

    empty_ch = 0
    for p in ProductModel.objects.all().only("id", "sales_channels"):
        if not p.sales_channels:
            p.sales_channels = ["B2B", "B2B_API", "B2C_API"]
            p.save(update_fields=["sales_channels"])
            empty_ch += 1

    cert_product_ids = set(
        ProductMedia.objects.filter(role="CERTIFICATE_PDF").values_list("product_id", flat=True)
    )
    cleared_gia = (
        ProductModel.objects.filter(certificate_agency="GIA", certificate_number="")
        .exclude(id__in=cert_product_ids)
        .update(certificate_agency="")
    )
    logger.info(
        "catalog.0006 backfill: sales_channels=%s, cleared_fake_gia=%s",
        empty_ch,
        cleared_gia,
    )


